    "page.connType.shadow.h2.find-shadow-matches": "Zoek Schaduw Wedstrijden",
    "page.connType.shadow.p.calculate-your-four-totem-animals-then": "Bereken je vier totemdieren en blader vervolgens door de opt-in directory voor mensen die dit type verbinding met jou delen.",
    "page.connType.shadow.btn.totem-connections-directory": "Totem Connections Gids",
    "page.connType.shadow.btn.totem-animals-calculator": "Totem Animals Calculator",
    "page.connType.mirror-opposite.section-label.connection-type": "Verbindingstype",
    "page.connType.mirror-opposite.h1.mirror-opposite": "Spiegelbeeld",
    "page.connType.mirror-opposite.p.opposites-on-the-zodiac-wheel-six": "Tegenpolen op het dierenriemwiel — zes tekens van elkaar verwijderd, recht tegenover elkaar aan de cirkel. Ideaal om blinde vlekken te reflecteren en te leren vanuit een radicaal ander perspectief.",
    "page.connType.mirror-opposite.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
    "page.connType.mirror-opposite.p.opposites-on-the-zodiac-wheel-six.2": "Tegenovergestelde tekens op de dierenriemwiel — zes tekens van elkaar verwijderd, elkaar direct tegemoetkomend over de cirkel. Deze connecties zijn perfect om onszelf te weerspiegelen en elkaars blinde vlekken te zien — omdat ze letterlijk in de tegenovergestelde richting staan van jou! Dit kan leiden tot pittige discussies, maar zolang je genoeg respect meebrengt, valt hier veel te leren van je spiegels — jullie beiden kunnen dingen zien die de ander niet kan, dus zolang je elkaar vertrouwt en te goeder trouw handelt, kan dit een zeer nuttige en mooie verbinding zijn. Het zal zeker dingen interessant houden, omdat zij ongetwijfeld een andere kijk op de zaken zullen hebben dan jij, soms zo radicaal anders dat je niet eens dacht dat het mogelijk was!",
    "page.connType.mirror-opposite.h3.other-connection-types": "Andere verbindingssoorten",
    "page.connType.mirror-opposite.li.rainbow": "<a href=\"connection-rainbow.html?v=20260807\">Regenboog</a>",
