    "page.connType.values-trine.li.same-as-me": "<a href=\"connection-same-as-me.html?v=20260807\">Soos-Ek</a>",
    "page.connType.values-trine.h2.find-values-trine-matches": "Vind Waardes Trien Wedstryde",
    "page.connType.values-trine.p.calculate-your-four-totem-animals-then": "Bereken jou vier totemdiere, en blaai dan deur die opsie-gids vir mense wat hierdie verbindingssoort met jou deel.",
